import sys
from heapq import heappop, heappush

def main():
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index+1])
    index += 2

    a = list(map(int, data[index:index+n]))
    c = list(map(int, data[index+n:index+2*n]))
    index += 2*n

    customers = []
    for _ in range(m):
        t_j = int(data[index]) - 1
        d_j = int(data[index+1])
        index += 2
        customers.append((t_j, d_j))

    heap = []
    for i in range(n):
        if a[i] > 0:
            heappush(heap, (c[i], i, a[i]))

    results = []
    for t_j, d_j in customers:
        cost = 0
        while d_j > 0:
            if heap:
                current_cost, current_type, current_remaining = heappop(heap)
                if current_remaining >= d_j:
                    cost += current_cost * d_j
                    current_remaining -= d_j
                    d_j = 0
                else:
                    cost += current_cost * current_remaining
                    d_j -= current_remaining
                    if current_remaining > 0:
                        heappush(heap, (current_cost, current_type, current_remaining))
            else:
                results.append(0)
                break

        if d_j == 0:
            results.append(cost)
        else:
            results.append(0)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

from sys import stdin, stdout

def main():
    n, m = map(int, stdin.readline().split())
    a = list(map(int, stdin.readline().split()))
    c = list(map(int, stdin.readline().split()))

    inventory = [(a[i], i) for i in range(n)]
    inventory.sort()
    costs = [0] * m

    for j in range(m):
        t_j, d_j = map(int, stdin.readline().split())
        t_j -= 1
        current_cost = 0
        while d_j > 0:
            if inventory[t_j][0] > 0:
                inventory[t_j] = (inventory[t_j][0] - 1, inventory[t_j][1])
                current_cost += c[t_j]
                d_j -= 1
            else:
                found = False
                for k in range(t_j, n):
                    if inventory[k][0] > 0:
                        inventory[k] = (inventory[k][0] - 1, inventory[k][1])
                        current_cost += c[inventory[k][1]]
                        d_j -= 1
                        found = True
                        break
                if not found:
                    break

        costs[j] = current_cost

    for cost in costs:
        stdout.write(f"{cost}\n")

if __name__ == "__main__":
    main()
